import sys
import json
import re
import operator

def evaluate_expression(expr, metrics):
    # Replace metric names with their values
    for name, value in metrics.items():
        expr = expr.replace(name, str(value))

    # Tokenize the expression
    tokens = re.findall(r'(\d+\.?\d*|[+\-*/()]|[a-zA-Z_][a-zA-Z0-9_]*|[a-zA-Z_])', expr)
    tokens = [t for t in tokens if t not in [' ', '']]

    # Convert tokens to numbers where possible
    def token_to_num(token):
        try:
            return float(token)
        except ValueError:
            return token

    tokens = [token_to_num(t) for t in tokens]

    # Operator precedence and functions
    precedence = {'*': 3, '/': 3, '+': 2, '-': 2}
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}

    # Shunting-yard algorithm to convert infix to postfix notation
    output = []
    ops_stack = []

    for token in tokens:
        if isinstance(token, (int, float)):
            output.append(token)
        elif token in precedence:
            while (ops_stack and ops_stack[-1] != '(' and
                   precedence.get(ops_stack[-1], 0) >= precedence.get(token, 0)):
                output.append(ops_stack.pop())
            ops_stack.append(token)
        elif token == '(':
            ops_stack.append(token)
        elif token == ')':
            while ops_stack and ops_stack[-1] != '(':
                output.append(ops_stack.pop())
            ops_stack.pop()  # Remove '('

    while ops_stack:
        output.append(ops_stack.pop())

    # Evaluate postfix expression
    stack = []
    for token in output:
        if isinstance(token, (int, float)):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[token](a, b))

    return stack[0] if stack else 0

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    config_path = sys.argv[1]
    token = sys.argv[2]

    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except (IOError, json.JSONDecodeError):
        sys.exit(1)

    scope, subject = token.split(':', 1)
    if scope != config['required_scope']:
        print("Access denied")
        sys.exit(1)

    metrics = config['metrics']
    widgets = config['widgets']

    html_lines = [
        '<html><head><title>Report</title></head><body><table>',
        '<tr><td>Name</td><td>Value</td></tr>'
    ]

    for widget in widgets:
        expr = widget['expression']
        value = evaluate_expression(expr, metrics)
        html_lines.append(f'<tr><td>{widget["name"]}</td><td>{value}</td></tr>')

    html_lines.append('</table></body></html>')
    html_content = '\n'.join(html_lines)

    with open('report.html', 'w') as f:
        f.write(html_content)

if __name__ == '__main__':
    main()

import sys
import json
import operator
import html

def evaluate_expression(expr, metrics):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i] == ' ':
            i += 1
            continue
        if expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        elif expr[i].isdigit():
            num = ''
            while i < n and expr[i].isdigit():
                num += expr[i]
                i += 1
            tokens.append(num)
        else:
            if expr[i] in metrics:
                tokens.append(expr[i])
            i += 1
    # Convert infix to postfix notation (Reverse Polish Notation)
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    operators = []
    for token in tokens:
        if token.isdigit():
            output.append(token)
        elif token in metrics:
            output.append(metrics[token])
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()  # Remove '('
        else:
            while operators and operators[-1] != '(' and precedence.get(operators[-1], 0) >= precedence.get(token, 0):
                output.append(operators.pop())
            operators.append(token)
    while operators:
        output.append(operators.pop())
    # Evaluate postfix expression
    stack = []
    for token in output:
        if isinstance(token, str) and token.isdigit():
            stack.append(float(token))
        elif token in metrics:
            stack.append(metrics[token])
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
    return stack[0] if stack else 0

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py <config.json> <token>")
        sys.exit(1)

    config_path = sys.argv[1]
    token = sys.argv[2]

    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading config file: {e}")
        sys.exit(1)

    required_subject = config.get('required_subject')
    required_scope = config.get('required_scope')
    token_parts = token.split(':', 1)
    if len(token_parts) != 2:
        print("Invalid token format")
        sys.exit(1)

    subject, scope = token_parts
    if subject != required_subject or scope != required_scope:
        print("Access denied")
        sys.exit(1)

    metrics = config.get('metrics', {})
    widgets = config.get('widgets', [])

    results = []
    for widget in widgets:
        expr = widget.get('expression', '')
        try:
            result = evaluate_expression(expr, metrics)
            results.append(f"{result}")
        except:
            results.append("Error evaluating expression")

    html_content = f"""<html><head><title>Report</title></head><body><table>
    <tr><th>Name</th><th>Value</th></tr>
    {''.join(f'<tr><td>{widget["name"]}</td><td>{result}</td></tr>' for widget, result in zip(widgets, results))}
    </table></body></html>"""
    with open('report.html', 'w') as f:
        f.write(html_content)

if __name__ == "__main__":
    main()
